edits.old:
if (const auto found = compiled_.find(&schema); found != compiled_.end())
  return found->second;
const auto id = New();
compiled_[&schema] = id;

edits.new:
#if LIE_C17_SAMPLING
    if (auto found = compiled_.get(&schema))
      return *found;
    const auto id = New();
    compiled_.assign(&schema, id);
#else
    if (const auto found = compiled_.find(&schema); found != compiled_.end())
      return found->second;
    const auto id = New();
    compiled_[&schema] = id;
#endif

#if LIE_C17_SAMPLING
  lie_gufo::SchemaMemo compiled_;
#else
  std::map<const json::Value*, std::uint32_t> compiled_;
#endif
